CREATE TABLE users(id uuid PRIMARY KEY,profile_picture varchar(255),first_name varchar(120) NOT NULL,last_name varchar(120) NOT NULL,email varchar(150) NOT NULL UNIQUE,password varchar(255) NOT NULL,salt varchar(255) NOT NULL,is_active boolean NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,phone varchar(20));
CREATE TABLE branches(id uuid PRIMARY KEY,name varchar(255) NOT NULL UNIQUE,code varchar(255) NOT NULL UNIQUE,address text,phone varchar(255),logo_url varchar(255),is_active boolean NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL);
CREATE TABLE permissions(id uuid PRIMARY KEY,name varchar(255) NOT NULL UNIQUE,description varchar(1000),created_at timestamptz,updated_at timestamptz);
CREATE TABLE roles(id uuid PRIMARY KEY,name varchar(100) NOT NULL,description text,is_system boolean NOT NULL,scope varchar(20) NOT NULL,is_active boolean NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,branch_id uuid REFERENCES branches(id),CONSTRAINT roles_scope_check CHECK(scope IN ('PLATFORM','BRANCH')));
CREATE TABLE role_permissions(role_id uuid NOT NULL REFERENCES roles(id),permission_id uuid NOT NULL REFERENCES permissions(id),CONSTRAINT uk_role_permission UNIQUE(role_id,permission_id));
CREATE TABLE user_branches(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),branch_id uuid NOT NULL REFERENCES branches(id),created_at timestamptz NOT NULL,CONSTRAINT uk_user_branch UNIQUE(user_id,branch_id));
CREATE TABLE user_branch_roles(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),branch_id uuid NOT NULL REFERENCES branches(id),role_id uuid NOT NULL REFERENCES roles(id),created_at timestamptz NOT NULL,CONSTRAINT uk_user_branch_role UNIQUE(user_id,branch_id,role_id));
CREATE TABLE user_platform_roles(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),role_id uuid NOT NULL REFERENCES roles(id),created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,CONSTRAINT uk_user_platform_role UNIQUE(user_id,role_id));
CREATE INDEX idx_ubr_user_branch ON user_branch_roles(user_id,branch_id);
CREATE INDEX idx_user_platform_roles_role ON user_platform_roles(role_id);
